package com.onrender.smartnf.health;
import java.time.*;import java.util.*;import java.sql.Date;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import static com.onrender.smartnf.health.ShoppingListModels.*;
@Service public class ShoppingListService {
 private final JdbcTemplate jdbc;public ShoppingListService(JdbcTemplate jdbc){this.jdbc=jdbc;}
 private record Row(UUID id,long revision,boolean deleted,LocalDate date,LocalDate from,LocalDate to,String kind,String request,String hash){}
 private LocalDate local(Date d){return d==null?null:d.toLocalDate();}
 private List<Row> rows(long member,UUID id){return jdbc.query("SELECT * FROM shopping_lists WHERE member_id=? AND id=?",(r,n)->new Row(UUID.fromString(r.getString("id")),r.getLong("revision"),r.getBoolean("deleted"),local(r.getDate("shopping_date")),local(r.getDate("source_from")),local(r.getDate("source_to")),r.getString("source_kind"),r.getString("last_request_id"),r.getString("last_request_hash")),member,id.toString());}
 private Row find(long member,UUID id){return rows(member,id).stream().findFirst().orElse(null);}
 private Saved view(long member,Row r){
  var measures=new java.util.HashMap<Integer,List<Measure>>();
  if(!r.deleted())jdbc.query("SELECT q.* FROM shopping_item_quantities q JOIN shopping_lists l ON l.id=q.list_id WHERE l.member_id=? AND q.list_id=?",(java.sql.ResultSet x)->{measures.computeIfAbsent(x.getInt("entry_no"),k->new ArrayList<>()).add(new Measure(x.getBigDecimal("amount"),x.getString("unit"),x.getString("evidence")));},member,r.id().toString());
  var items=r.deleted()?List.<Item>of():jdbc.query("SELECT i.* FROM shopping_list_items i JOIN shopping_lists l ON l.id=i.list_id WHERE l.member_id=? AND i.list_id=? ORDER BY i.entry_no",(x,n)->new Item(x.getString("food_id"),x.getString("food_name"),x.getBigDecimal("grams"),measures.getOrDefault(x.getInt("entry_no"),List.of()).stream().sorted(Comparator.comparing(Measure::unit)).toList()),member,r.id().toString());
  return new Saved(r.id(),r.revision(),r.deleted(),r.date(),r.from(),r.to(),r.kind(),items);
 }
 @Transactional(readOnly=true) public Saved get(long member,UUID id){Row r=find(member,id);if(r==null||r.deleted())throw new HealthException(404,"저장된 장보기 목록을 찾을 수 없습니다.");return view(member,r);}
 @Transactional(readOnly=true) public Range range(long member,LocalDate from,LocalDate to){date(from);date(to);if(from.isAfter(to)||java.time.temporal.ChronoUnit.DAYS.between(from,to)>62)throw HealthException.invalid();var ids=jdbc.query("SELECT id FROM shopping_lists WHERE member_id=? AND deleted=FALSE AND shopping_date BETWEEN ? AND ? ORDER BY shopping_date,updated_at DESC,id LIMIT 201",(r,n)->UUID.fromString(r.getString(1)),member,Date.valueOf(from),Date.valueOf(to));return new Range(ids.stream().limit(200).map(id->get(member,id)).toList(),ids.size()>200);}
 @Transactional(readOnly=true) public List<DayCount> counts(long member,LocalDate from,LocalDate to){date(from);date(to);if(from.isAfter(to)||java.time.temporal.ChronoUnit.DAYS.between(from,to)>62)throw HealthException.invalid();return jdbc.query("SELECT shopping_date,COUNT(*) FROM shopping_lists WHERE member_id=? AND deleted=FALSE AND shopping_date BETWEEN ? AND ? GROUP BY shopping_date ORDER BY shopping_date",(r,n)->new DayCount(r.getDate(1).toLocalDate(),r.getInt(2)),member,Date.valueOf(from),Date.valueOf(to));}
 private void lock(long member){if(jdbc.queryForList("SELECT id FROM members WHERE id=? FOR UPDATE",Long.class,member).isEmpty())throw new HealthException(403,"회원 상태를 확인해 주세요.");}
 @Transactional public Saved save(long member,Save input){
  Save s=validate(input);lock(member);Row old=find(member,s.id());String hash=saveHash(s);
  if(old!=null&&old.request().equals(s.requestId().toString())){if(!old.hash().equals(hash))throw HealthException.conflict();return view(member,old);}
  if((old==null?0:old.revision())!=s.expectedRevision()||old!=null&&old.deleted())throw HealthException.conflict();long next=s.expectedRevision()+1;
  if(old==null){try{jdbc.update("INSERT INTO shopping_lists(id,member_id,revision,deleted,shopping_date,source_from,source_to,source_kind,last_request_id,last_request_hash,updated_at) VALUES(?,?,?,FALSE,?,?,?,?,?,?,?)",s.id().toString(),member,next,Date.valueOf(s.shoppingDate()),Date.valueOf(s.sourceFrom()),Date.valueOf(s.sourceTo()),s.sourceKind(),s.requestId().toString(),hash,LocalDateTime.now(ZoneOffset.UTC));}catch(org.springframework.dao.DuplicateKeyException e){throw HealthException.conflict();}}
  else jdbc.update("UPDATE shopping_lists SET revision=?,shopping_date=?,source_from=?,source_to=?,source_kind=?,last_request_id=?,last_request_hash=?,updated_at=? WHERE member_id=? AND id=?",next,Date.valueOf(s.shoppingDate()),Date.valueOf(s.sourceFrom()),Date.valueOf(s.sourceTo()),s.sourceKind(),s.requestId().toString(),hash,LocalDateTime.now(ZoneOffset.UTC),member,s.id().toString());
  jdbc.update("DELETE FROM shopping_item_quantities WHERE list_id=?",s.id().toString());jdbc.update("DELETE FROM shopping_list_items WHERE list_id=?",s.id().toString());int i=0;for(var item:s.items()){int entry=i++;jdbc.update("INSERT INTO shopping_list_items(list_id,entry_no,food_id,food_name,grams) VALUES(?,?,?,?,?)",s.id().toString(),entry,item.foodId(),item.name(),item.grams());for(var q:item.quantities())jdbc.update("INSERT INTO shopping_item_quantities(list_id,entry_no,unit,amount,evidence) VALUES(?,?,?,?,?)",s.id().toString(),entry,q.unit(),q.amount(),q.evidence());}return view(member,find(member,s.id()));
 }
 @Transactional public Saved delete(long member,UUID id,Delete d){
  if(d==null||d.requestId()==null||d.expectedRevision()==null||d.expectedRevision()<1||d.expectedRevision()==Long.MAX_VALUE)throw HealthException.invalid();lock(member);Row old=find(member,id);if(old==null)throw new HealthException(404,"목록을 찾을 수 없습니다.");String hash=hash("DELETE",id+":"+d);
  if(old.request().equals(d.requestId().toString())){if(!old.hash().equals(hash))throw HealthException.conflict();return view(member,old);}
  if(old.deleted()||old.revision()!=d.expectedRevision())throw HealthException.conflict();jdbc.update("DELETE FROM shopping_item_quantities WHERE list_id=?",id.toString());jdbc.update("DELETE FROM shopping_list_items WHERE list_id=?",id.toString());jdbc.update("UPDATE shopping_lists SET deleted=TRUE,revision=?,shopping_date=NULL,source_from=NULL,source_to=NULL,source_kind='',last_request_id=?,last_request_hash=?,updated_at=? WHERE member_id=? AND id=?",old.revision()+1,d.requestId().toString(),hash,LocalDateTime.now(ZoneOffset.UTC),member,id.toString());return view(member,find(member,id));
 }
 private static String saveHash(Save s){try{var bytes=new java.io.ByteArrayOutputStream();var out=new java.io.DataOutputStream(bytes);out.writeUTF(s.id().toString());out.writeLong(s.expectedRevision());out.writeUTF(s.shoppingDate().toString());out.writeUTF(s.sourceFrom().toString());out.writeUTF(s.sourceTo().toString());out.writeUTF(s.sourceKind());out.writeInt(s.items().size());for(var item:s.items()){out.writeUTF(item.foodId());out.writeUTF(item.name());out.writeUTF(item.grams()==null?"":item.grams().toPlainString());if(!item.quantities().isEmpty()){out.writeUTF("multi-unit-v1");out.writeInt(item.quantities().size());for(var q:item.quantities()){out.writeUTF(q.unit());out.writeUTF(q.amount().toPlainString());out.writeUTF(q.evidence());}}}out.flush();return hash("SAVE",HexFormat.of().formatHex(bytes.toByteArray()));}catch(java.io.IOException e){throw new IllegalStateException(e);}}
 private static String hash(String operation,String body){try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest((operation+"\n"+body).getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
